package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.deser.std.FromStringDeserializer;
import com.fasterxml.jackson.databind.deser.std.InvalidFormatException;
import com.fasterxml.jackson.databind.exc.InvalidFormatException;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.io.File;
import java.io.IOException;
import java.math.*;
import java.net.InetAddress;
import java.net.InetSocketAddress;
import java.net.URI;
import java.net.URL;
import java.nio.charset.Charset;
import java.util.*;
import java.util.Currency;
import java.util.Locale;
import java.util.TimeZone;
import java.util.regex.Pattern;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.*;

public class Std__deserialize_TriageGen1Test {

    private DeserializationContext ctxt;
    private JsonParser parser;

    // Mocking the protected inner class Std
    private static class TestStd extends FromStringDeserializer.Std {
        protected TestStd(Class<?> valueType, int kind) {
            super(valueType, kind);
        }

        // Expose protected method for testing
        @Override
        public Object _deserialize(String value, DeserializationContext ctxt) throws IOException {
            return super._deserialize(value, ctxt);
        }
    }

    // Constants for kinds (assuming these values based on Jackson source)
    private static final int STD_FILE = 1;
    private static final int STD_URL = 2;
    private static final int STD_URI = 3;
    private static final int STD_CLASS = 4;
    private static final int STD_JAVA_TYPE = 5;
    private static final int STD_CURRENCY = 6;
    private static final int STD_PATTERN = 7;
    private static final int STD_LOCALE = 8;
    private static final int STD_CHARSET = 9;
    private static final int STD_TIME_ZONE = 10;
    private static final int STD_INET_ADDRESS = 11;
    private static final int STD_INET_SOCKET_ADDRESS = 12;
    private static final int UNKNOWN_KIND = 99;

    @Before
    public void setup() {
        ctxt = mock(DeserializationContext.class);
        parser = mock(JsonParser.class);
        when(ctxt.getParser()).thenReturn(parser);
    }

    @Test
    public void testFile() throws IOException {
        TestStd std = new TestStd(File.class, STD_FILE);
        assertEquals(new File("test.txt"), std._deserialize("test.txt", ctxt));
    }

    @Test
    public void testUrl() throws IOException {
        TestStd std = new TestStd(URL.class, STD_URL);
        assertEquals(new URL("http://localhost"), std._deserialize("http://localhost", ctxt));
    }

    @Test
    public void testUri() throws IOException {
        TestStd std = new TestStd(URI.class, STD_URI);
        assertEquals(URI.create("http://localhost"), std._deserialize("http://localhost", ctxt));
    }

    @Test
    public void testClassSuccess() throws Exception {
        TestStd std = new TestStd(Object.class, STD_CLASS);
        when(ctxt.findClass("java.lang.String")).thenReturn(String.class);
        assertEquals(String.class, std._deserialize("java.lang.String", ctxt));
    }

    @Test
    public void testClassFailure() throws Exception {
        TestStd std = new TestStd(Object.class, STD_CLASS);
        when(ctxt.findClass("invalid")).thenThrow(new RuntimeException("not found"));
        when(ctxt.instantiationException(any(), any())).thenThrow(new RuntimeException("instantiation error"));

        try {
            std._deserialize("invalid", ctxt);
            fail("Should have thrown exception");
        } catch (RuntimeException e) {
            assertEquals("instantiation error", e.getMessage());
        }
    }

    @Test
    public void testJavaType() throws IOException {
        TestStd std = new TestStd(Object.class, STD_JAVA_TYPE);
        TypeFactory tf = TypeFactory.defaultInstance();
        when(ctxt.getTypeFactory()).thenReturn(tf);
        JavaType jt = tf.constructFromCanonical("java.lang.String");
        assertEquals(jt, std._deserialize("java.lang.String", ctxt));
    }

    @Test
    public void testCurrency() throws IOException {
        TestStd std = new TestStd(Currency.class, STD_CURRENCY);
        assertEquals(Currency.getInstance("USD"), std._deserialize("USD", ctxt));
    }

    @Test
    public void testPattern() throws IOException {
        TestStd std = new TestStd(Pattern.class, STD_PATTERN);
        assertEquals(Pattern.compile(".*"), std._deserialize(".*", ctxt));
    }

    @Test
    public void testLocaleSingle() throws IOException {
        TestStd std = new TestStd(Locale.class, STD_LOCALE);
        assertEquals(new Locale("en"), std._deserialize("en", ctxt));
    }

    @Test
    public void testLocaleTwo() throws IOException {
        TestStd std = new TestStd(Locale.class, STD_LOCALE);
        assertEquals(new Locale("en", "US"), std._deserialize("en_US", ctxt));
    }

    @Test
    public void testLocaleThree() throws IOException {
        TestStd std = new TestStd(Locale.class, STD_LOCALE);
        assertEquals(new Locale("en", "US", "POSIX"), std._deserialize("en_US_POSIX", ctxt));
    }

    @Test
    public void testCharset() throws IOException {
        TestStd std = new TestStd(Charset.class, STD_CHARSET);
        assertEquals(Charset.forName("UTF-8"), std._deserialize("UTF-8", ctxt));
    }

    @Test
    public void testTimeZone() throws IOException {
        TestStd std = new TestStd(TimeZone.class, STD_TIME_ZONE);
        assertEquals(TimeZone.getTimeZone("UTC"), std._deserialize("UTC", ctxt));
    }

    @Test
    public void testInetAddress() throws IOException {
        TestStd std = new TestStd(InetAddress.class, STD_INET_ADDRESS);
        assertEquals(InetAddress.getByName("127.0.0.1"), std._deserialize("127.0.0.1", ctxt));
    }

    @Test
    public void testInetSocketAddressBracketedNoPort() throws IOException {
        TestStd std = new TestStd(InetSocketAddress.class, STD_INET_SOCKET_ADDRESS);
        InetSocketAddress expected = new InetSocketAddress("[::1]", 0);
        assertEquals(expected, std._deserialize("[::1]", ctxt));
    }

    @Test
    public void testInetSocketAddressBracketedWithPort() throws IOException {
        TestStd std = new TestStd(InetSocketAddress.class, STD_INET_SOCKET_ADDRESS);
        InetSocketAddress expected = new InetSocketAddress("[::1]", 8080);
        assertEquals(expected, std._deserialize("[::1]:8080", ctxt));
    }

    @Test
    public void testInetSocketAddressBracketedMissingClosing() throws IOException {
        TestStd std = new TestStd(InetSocketAddress.class, STD_INET_SOCKET_ADDRESS);
        try {
            std._deserialize("[::1", ctxt);
            fail("Should have thrown InvalidFormatException");
        } catch (InvalidFormatException e) {
            assertTrue(e.getMessage().contains("Bracketed IPv6 address must contain closing bracket"));
        }
    }

    @Test
    public void testInetSocketAddressHostPort() throws IOException {
        TestStd std = new TestStd(InetSocketAddress.class, STD_INET_SOCKET_ADDRESS);
        InetSocketAddress expected = new InetSocketAddress("localhost", 80);
        assertEquals(expected, std._deserialize("localhost:80", ctxt));
    }

    @Test
    public void testInetSocketAddressSimpleHost() throws IOException {
        TestStd std = new TestStd(InetSocketAddress.class, STD_INET_SOCKET_ADDRESS);
        InetSocketAddress expected = new InetSocketAddress("localhost", 0);
        assertEquals(expected, std._deserialize("localhost", ctxt));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testUnknownKind() throws IOException {
        TestStd std = new TestStd(Object.class, UNKNOWN_KIND);
        std._deserialize("anything", ctxt);
    }
}
